from pathlib import Path
import pandas as pd,numpy as np,json
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'powerbi/data';D.mkdir(parents=True,exist_ok=True)
def read(name):return pd.read_csv(ROOT/'data'/f'olist_{name}_dataset.csv')
o=read('orders');items=read('order_items');reviews=read('order_reviews');customers=read('customers');sellers=read('sellers')
o=o[o.order_id.isin(items.order_id)].copy();purchase=pd.to_datetime(o.order_purchase_timestamp);delivery=pd.to_datetime(o.order_delivered_customer_date);estimate=pd.to_datetime(o.order_estimated_delivery_date)
o['delivered_valid']=((o.order_status=='delivered')&delivery.notna()&estimate.notna()).astype(int)
o['is_late']=((o.delivered_valid==1)&(delivery.dt.normalize()>estimate.dt.normalize())).astype(int)
o['is_cancelled']=(o.order_status=='canceled').astype(int)
o['lead_time_days']=((delivery-purchase).dt.total_seconds()/86400).where((o.delivered_valid==1)&(delivery>=purchase)).round(4)
o['delay_days']=(delivery.dt.normalize()-estimate.dt.normalize()).dt.days.where(o.delivered_valid==1)
reviews=reviews.sort_values(['review_answer_timestamp','review_creation_date','review_id'],kind='stable',na_position='first').drop_duplicates('order_id',keep='last')
o=o.merge(reviews[['order_id','review_score']],on='order_id',how='left',validate='one_to_one').merge(customers[['customer_id','customer_state']],on='customer_id',validate='many_to_one')
o['has_occurrence']=((o.is_late==1)|(o.is_cancelled==1)).astype(int)
o[['order_id','delivered_valid','is_late','is_cancelled','lead_time_days','review_score','has_occurrence']].to_csv(D/'olist_orders_enriched.csv',index=False)
fact=items.merge(o[['order_id','customer_id','order_purchase_timestamp','is_late','is_cancelled','lead_time_days']],on='order_id',validate='many_to_one').rename(columns={'product_id':'product_key','seller_id':'seller_key','customer_id':'customer_key','is_late':'is_delayed'})
fact['date_key']=pd.to_datetime(fact.order_purchase_timestamp).dt.strftime('%Y%m%d').astype(int)
fact[['order_id','order_item_id','product_key','seller_key','customer_key','date_key','price','freight_value','is_delayed','is_cancelled','lead_time_days']].to_csv(D/'fact_orders.csv',index=False)
products=read('products');translation=pd.read_csv(ROOT/'data/product_category_name_translation.csv')
products=products.merge(translation,on='product_category_name',how='left',validate='many_to_one')
products['product_category_name_english']=products.product_category_name_english.fillna('unknown')
products[['product_id','product_category_name_english']].rename(columns={'product_id':'product_key','product_category_name_english':'category_name_en'}).to_csv(D/'dim_product.csv',index=False)
customers[['customer_id','customer_unique_id','customer_city','customer_state']].rename(columns={'customer_id':'customer_key','customer_city':'city','customer_state':'state'}).to_csv(D/'dim_customer.csv',index=False)
sellers[['seller_id','seller_city','seller_state']].rename(columns={'seller_id':'seller_key','seller_city':'city','seller_state':'state'}).to_csv(D/'dim_seller.csv',index=False)
start=pd.to_datetime(o.order_purchase_timestamp).min().year;end=pd.to_datetime(o.order_purchase_timestamp).max().year
dates=pd.date_range(f'{start}-01-01',f'{end}-12-31');date=pd.DataFrame({'date_key':dates.strftime('%Y%m%d').astype(int),'full_date':dates.strftime('%Y-%m-%d'),'year':dates.year,'quarter':dates.quarter,'month':dates.month,'month_name':dates.month_name(),'day_of_month':dates.day,'day_name':dates.day_name(),'day_of_week':dates.dayofweek+1,'is_weekend':(dates.dayofweek>=5).astype(int),'year_month':dates.strftime('%Y-%m')});date.to_csv(D/'dim_date.csv',index=False)
review_fact=reviews.merge(items[['order_id','seller_id']].drop_duplicates(),on='order_id',validate='one_to_many');review_fact['date_key']=pd.to_datetime(review_fact.review_creation_date).dt.strftime('%Y%m%d').astype(int);review_fact['response_time_days']=(pd.to_datetime(review_fact.review_answer_timestamp)-pd.to_datetime(review_fact.review_creation_date)).dt.total_seconds()/86400
review_fact[['review_id','order_id','seller_id','date_key','review_score','response_time_days']].rename(columns={'seller_id':'seller_key'}).to_csv(D/'fact_reviews.csv',index=False)
prod=pd.read_csv(D/'dim_product.csv');base=items.merge(o[['order_id','customer_state','delivered_valid','is_late','is_cancelled','has_occurrence','lead_time_days','delay_days','review_score']],on='order_id',validate='many_to_one').merge(prod,left_on='product_id',right_on='product_key',how='left',validate='many_to_one');base['category_name_en']=base.category_name_en.fillna('unknown')
base['risk_value']=base.price*base.has_occurrence
fin=base.groupby('category_name_en').agg(total_orders=('order_id','nunique'),total_revenue=('price','sum'),total_freight=('freight_value','sum'),revenue_at_risk=('risk_value','sum'),cancelled_items=('is_cancelled','sum'),late_delivered_items=('is_late','sum')).reset_index().rename(columns={'category_name_en':'category'})
fin['avg_ticket']=fin.total_revenue/fin.total_orders;fin['pct_revenue_at_risk']=fin.revenue_at_risk/fin.total_revenue;fin['revenue_rank']=fin.total_revenue.rank(method='min',ascending=False).astype(int);fin['revenue_percentile']=(fin.total_revenue.rank(method='min')-1)/(len(fin)-1);fin['revenue_quartile']=np.ceil(fin.total_revenue.rank(method='first',ascending=False)/len(fin)*4).astype(int);fin['company_avg_ticket']=fin.avg_ticket.mean();fin['company_avg_pct_revenue_at_risk']=fin.pct_revenue_at_risk.mean();fin['financial_health_tier']=np.where(fin.pct_revenue_at_risk>=.15,'High Financial Risk',np.where(fin.pct_revenue_at_risk>=.07,'Moderate Financial Risk','Financially Healthy'));fin.to_csv(D/'vw_financial_health.csv',index=False)
order_value=items.groupby('order_id').agg(order_revenue=('price','sum'),order_freight=('freight_value','sum'));delivery=o[o.delivered_valid==1].merge(order_value,on='order_id');delivery['ratio']=delivery.order_freight/delivery.order_revenue
log=delivery.groupby('customer_state').agg(total_delivered_orders=('order_id','nunique'),avg_lead_time_days=('lead_time_days','mean'),avg_delay_days=('delay_days','mean'),pct_delayed=('is_late','mean'),avg_freight_value=('order_freight','mean'),total_revenue=('order_revenue','sum'),avg_freight_to_revenue_ratio=('ratio','mean')).reset_index()
regions={**dict.fromkeys(['AC','AP','AM','PA','RO','RR','TO'],'Norte'),**dict.fromkeys(['AL','BA','CE','MA','PB','PE','PI','RN','SE'],'Nordeste'),**dict.fromkeys(['DF','GO','MT','MS'],'Centro-Oeste'),**dict.fromkeys(['ES','MG','RJ','SP'],'Sudeste'),**dict.fromkeys(['PR','RS','SC'],'Sul')};pd.DataFrame({'state_key':list(regions),'region':list(regions.values())}).to_csv(D/'dim_geography.csv',index=False);log['region']=log.customer_state.map(regions);log['lead_time_rank']=log.avg_lead_time_days.rank(method='dense').astype(int);log['lead_time_rank_in_region']=log.groupby('region').avg_lead_time_days.rank(method='dense').astype(int);log['national_avg_lead_time_days']=delivery.lead_time_days.mean();log['national_avg_pct_delayed']=delivery.is_late.mean();log['lead_time_vs_national_avg']=log.avg_lead_time_days-log.national_avg_lead_time_days;log['logistics_risk_tier']=np.where((log.pct_delayed<=.08)&(log.avg_lead_time_days<=12),'Efficient Region',np.where((log.pct_delayed<=.2)&(log.avg_lead_time_days<=20),'Moderate Delay Region','High Risk Region'));log.to_csv(D/'vw_logistics_regional.csv',index=False)
so=base.drop_duplicates(['seller_id','order_id']).copy();so['on_time']=np.where(so.delivered_valid==1,1-so.is_late,np.nan)
seller=base.groupby('seller_id').agg(total_items_sold=('order_id','size'),total_revenue=('price','sum'),avg_item_price=('price','mean')).join(so.groupby('seller_id').agg(total_orders=('order_id','nunique'),avg_review_score=('review_score','mean'),total_reviews=('review_score','count'),on_time_rate=('on_time','mean'))).reset_index().merge(sellers[['seller_id','seller_city','seller_state']],on='seller_id',validate='one_to_one')
seller['quality_rank']=seller[['avg_review_score','on_time_rate']].apply(tuple,axis=1).rank(method='dense',ascending=False).astype(int);seller['quality_rank_in_state']=seller.groupby('seller_state').quality_rank.rank(method='dense').astype(int);seller['revenue_quartile']=np.ceil(seller.total_revenue.rank(method='first',ascending=False)/len(seller)*4).astype(int);seller['company_avg_review_score']=seller.avg_review_score.mean();seller['company_avg_on_time_rate']=seller.on_time_rate.mean();seller['supplier_segment']=np.where((seller.avg_review_score>=4.5)&(seller.on_time_rate>=.9)&(seller.total_orders>=10),'Gold Partner',np.where((seller.avg_review_score>=3.5)&(seller.on_time_rate>=.7),'Regular Operation','Operational Risk'));seller.loc[seller.avg_review_score.isna()|seller.on_time_rate.isna(),'supplier_segment']='Insufficient Data';seller.to_csv(D/'vw_supplier_performance.csv',index=False)
dim=pd.read_csv(D/'dim_seller.csv');dim['segment_tier']=dim.seller_key.map(seller.set_index('seller_id').supplier_segment);dim.to_csv(D/'dim_seller.csv',index=False)
assert abs(fin.total_revenue.sum()-items.price.sum())<.01
assert int(log.total_delivered_orders.sum())==96470
print('Snapshots preparados:',len(o),'pedidos,',len(fin),'categorias,',len(seller),'fornecedores.')
